window.TESTS=(window.TESTS||[]).concat([{"id": "IFFCO01", "series": "iffco-agt", "num": "PYQ", "title": "IFFCO AGT 2026 - 19 Nov 2026 · 1 PM Shift Paper (Memory Based) · हल सहित (FREE)", "free": true, "fixed": true, "dur": 90, "mpq": 1, "neg": 0, "pdf": "papers/IFFCO_AGT_2026_19Nov_1PM_Shift_Solution.pdf", "qpdf": "papers/IFFCO_AGT_2026_19Nov_1PM_Shift_Question_Paper.pdf", "questions": [{"q": "कीटनाशी के लेबल पर पीला त्रिकोण (yellow triangle) किस विषाक्तता श्रेणी को दर्शाता है?\nOn a pesticide label, a yellow triangle indicates which toxicity category?", "o": ["मध्यम विषैला (Class III) / Moderately toxic (Class III)", "हल्का विषैला (Class IV) / Slightly toxic (Class IV)", "अत्यधिक विषैला (Class II) / Highly toxic (Class II)", "अति विषैला (Class I) / Extremely toxic (Class I)"], "a": 2, "e": "Insecticides Rules, 1971: लाल = Extremely toxic (I), पीला = Highly toxic (II), नीला = Moderately toxic (III), हरा = Slightly toxic (IV).\nRed = Class I, Yellow = Class II (highly toxic), Blue = Class III, Green = Class IV.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्तर बिहार की बलुई जलोढ़ भूमि में सब्जी फसलों में जड़-गाँठ सूत्रकृमि (root-knot nematode) का प्रमुख जड़ लक्षण क्या है?\nIn vegetable crops of the sandy alluvial tracts of North Bihar, root-knot nematode infestation is diagnosed by which root symptom?", "o": ["जड़ कॉलर को घेरते काले धब्बे / Dark lesions girdling the root collar", "दुर्गंधयुक्त सड़ी जड़ें / Rotted roots with foul odour", "धागे जैसी जड़ों का अधिक बनना / Thread-like root proliferation", "बारीक जड़ों पर फूली हुई गाँठें / Swollen galls on fine feeder roots"], "a": 3, "e": "Meloidogyne spp. के कारण जड़ों पर galls (गाँठें) बनती हैं, पौधा मुरझाया व बौना दिखता है।\nMeloidogyne spp. induce galls on roots; plants look stunted and wilted.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "पकते आम (मालदा) और अमरूद में फल मक्खी (fruit fly) का क्षति लक्षण क्या है?\nFruit fly infestation in ripening mango (Malda) and guava is characterised by which symptom?", "o": ["शिशु कीटों द्वारा कोमल टहनियों का रस चूसना / Nymphs sucking sap from tender shoots", "इल्ली द्वारा गूदे में सीधी सुरंग / Caterpillars boring straight tunnels in pulp", "गूदे के अंदर मैगट का खाना, छेद से रस रिसना / Maggots feeding inside pulp with oozing resin", "ग्रब द्वारा जड़ें खाना / Grubs feeding on roots"], "a": 2, "e": "Bactrocera dorsalis की मादा फल में अंडे देती है, मैगट गूदा खाकर सड़न पैदा करते हैं।\nBactrocera dorsalis oviposits in fruit; maggots feed on the pulp causing rotting and oozing.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "ऑपरेशन ग्रीन्स (Operation Greens) मुख्यतः किन उत्पादों के मूल्य स्थिर करने के लिए है?\nOperation Greens mainly aims to stabilise prices of which produce?", "o": ["दलहन और तिलहन / Pulses and oilseeds", "दूध और डेयरी उत्पाद / Milk and dairy products", "टमाटर, प्याज और आलू (TOP) / Tomato, onion and potato", "गेहूँ, धान और मक्का / Wheat, rice and maize"], "a": 2, "e": "Operation Greens (बजट 2018-19) TOP फसलों के लिए शुरू हुआ, 2020 में TOTAL (22 जल्दी खराब होने वाली फसलों) तक बढ़ाया गया।\nLaunched in 2018-19 for TOP crops; extended in 2020 to 22 perishables (TOP to TOTAL).", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "नियंत्रित मंडियों (APMC mandis) में कुशल मूल्य निर्धारण (price discovery) मुख्यतः किससे होता है?\nRegulated markets (APMC mandis) achieve efficient price discovery mainly through:", "o": ["किसान-खरीदार सीधा मोलभाव / Direct bargaining between farmer and buyer", "खुली नीलामी व प्रतिस्पर्धी बोली / Open auction and competitive bidding", "वस्तु विनिमय / Barter exchange of produce", "सरकार द्वारा तय मूल्य सूची / Fixed government-determined price lists"], "a": 1, "e": "नियंत्रित बाजार में open auction से कई खरीदार बोली लगाते हैं, जिससे उचित मूल्य मिलता है।\nOpen auction lets many buyers compete, giving a fair price to the farmer.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्तर-पूर्वी पहाड़ी क्षेत्र के नींबूवर्गीय बागों में विशेष मूलवृंत (rootstock) चुनने का मुख्य लाभ क्या है?\nIn citrus orchards of the NE hills, selecting a particular grafting rootstock mainly helps achieve which benefit?", "o": ["बौनापन और रोग प्रतिरोध / Dwarfing effect and disease resistance", "फल का रंग जल्दी आना / Faster fruit colour development", "फूल की पंखुड़ियों की संख्या बढ़ना / Increased flower petal count", "खुले फूलों में पराग जीवनक्षमता / Higher pollen viability"], "a": 0, "e": "Rootstock वृक्ष का आकार (vigour/dwarfing) और मृदा-जनित रोग (जैसे Phytophthora) प्रतिरोध नियंत्रित करता है, जैसे Trifoliate orange बौना व रोगरोधी।\nRootstocks control tree vigour and soil-borne disease tolerance, e.g. trifoliate orange gives dwarfing and Phytophthora tolerance.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "यदि कीटनाशी कर्मचारी की आँख में गिर जाए तो सही प्राथमिक उपचार क्या है?\nIf pesticide splashes into a worker's eyes, what is the correct first aid?", "o": ["तुरंत antibiotic मरहम लगाना / Apply antibiotic eye ointment at once", "आँख को धीरे से रगड़ना / Rub eyes gently to remove chemical", "साबुन के घोल से आँख धोना / Wash eyes with a soap solution", "साफ पानी से आँखें धोना / Flush eyes with clean water"], "a": 3, "e": "पलकें खोलकर कम से कम 15 मिनट साफ बहते पानी से धोएँ, फिर डॉक्टर को लेबल दिखाएँ।\nFlush with clean running water for at least 15 minutes, then see a doctor with the label.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मूल संचार मॉडल में 'डिकोडिंग' (decoding) का अर्थ ग्रहणकर्ता द्वारा क्या है?\nIn the basic communication model, 'decoding' refers to the receiver's:", "o": ["मूल संदेश की encoding / Encoding of the original message", "प्राप्त संदेश की व्याख्या / Interpretation of the message received", "संचार माध्यम चुनना / Selection of communication channel", "feedback संकेत भेजना / Transmission of feedback signal"], "a": 1, "e": "Sender संदेश को encode करता है, receiver उसे decode यानी समझकर अर्थ निकालता है।\nThe sender encodes; the receiver decodes, i.e. interprets the meaning.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उद्यम बजट (enterprise budget) मुख्यतः किसकी लागत और आय का अनुमान लगाने के लिए बनाया जाता है?\nAn enterprise budget is prepared mainly to estimate the costs and returns of:", "o": ["क्षेत्रीय कृषि बाजार / A regional agricultural market", "सहकारी विपणन समिति / A cooperative marketing society", "पूरे फार्म व्यवसाय / The entire farm business", "एक कृषि उद्यम / A single farm enterprise"], "a": 3, "e": "Enterprise budget एक फसल या पशु इकाई का होता है; पूरे फार्म का Whole farm budget कहलाता है।\nAn enterprise budget covers one crop or livestock unit; the whole farm needs a whole-farm budget.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "परीक्षण संकरण (test cross) मुख्यतः यह जानने के लिए किया जाता है कि जीनोटाइप:\nA test cross is primarily performed to determine whether an individual's genotype is:", "o": ["marker gene से पूर्ण सहलग्न है / Fully linked to a marker gene", "द्विगुणित या बहुगुणित है / Diploid or polyploid", "किसी लक्षण के लिए समयुग्मजी या विषमयुग्मजी है / Homozygous or heterozygous for a trait", "प्रेरित उत्परिवर्तन प्रतिरोधी है / Resistant to induced mutations"], "a": 2, "e": "F1 को अप्रभावी जनक (recessive parent) से क्रॉस किया जाता है; 1:1 अनुपात = heterozygous, सभी dominant = homozygous।\nThe individual is crossed with the recessive parent; 1:1 shows heterozygous, all dominant shows homozygous.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्तर बिहार में गन्ने के लाल सड़न (red rot) से ग्रसित तने को चीरने पर कौन सा आंतरिक लक्षण दिखता है?\nIn North Bihar, splitting a sugarcane stalk for red rot diagnosis reveals which internal symptom?", "o": ["गाँठों पर दुर्गंध वाली भूरी सड़न / Brown rot with foul smell at nodes", "काली कालिख जैसी फफूँद / Black sooty mould", "संवहन बंडलों में पीली धारियाँ / Yellow streaks in vascular bundles", "सफेद आड़ी पट्टियों वाला लाल ऊतक / Reddened tissue with white cross-bands"], "a": 3, "e": "Colletotrichum falcatum से गूदा लाल, बीच में सफेद आड़ी पट्टियाँ, और अल्कोहल जैसी गंध आती है।\nColletotrichum falcatum causes red pith with white transverse patches and an alcoholic smell.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "हुगली (प. बंगाल) के आलू में शीर्ष वृद्धि बिंदु का मरना और खोखला हृदय (hollow heart) किस तत्व की कमी दर्शाता है?\nIn potato crops of Hooghly, death of the terminal growing point along with hollow heart signals deficiency of:", "o": ["बोरॉन (B) / Boron (B)", "मैंगनीज (Mn) / Manganese (Mn)", "कैल्शियम (Ca) / Calcium (Ca)", "मॉलिब्डेनम (Mo) / Molybdenum (Mo)"], "a": 0, "e": "बोरॉन कोशिका भित्ति निर्माण व विभज्योतक (meristem) वृद्धि हेतु जरूरी है; कमी से growing point मरता है और कंद में खोखलापन आता है।\nBoron is needed for meristem growth and cell walls; its deficiency kills the growing point and causes hollow tubers.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "बुवाई से पहले Rhizobium कल्चर से बीज उपचार (रबी में मसूर, चना) सबसे अधिक लाभकारी है:\nSeed treatment with Rhizobium culture before sowing (lentil, chickpea in Rabi) is most beneficial for:", "o": ["दलहनी फसलें / Leguminous crops", "सब्जी फसलें / Vegetable crops", "तिलहनी फसलें / Oilseed crops", "अनाज फसलें / Cereal grain crops"], "a": 0, "e": "Rhizobium दलहनी जड़ों में ग्रंथियाँ (nodules) बनाकर सहजीवी नाइट्रोजन स्थिरीकरण करता है।\nRhizobium forms root nodules on legumes and fixes nitrogen symbiotically.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "6 कटाई मजदूर (harvesters) एक धान का खेत 5 दिन में काटते हैं। 4 मजदूर उसी खेत को कितने दिन में काटेंगे?\n6 harvesters can harvest a rice field in 5 days. How many days will 4 harvesters take?", "o": ["10 दिन / 10 days", "8 दिन / 8 days", "7.5 दिन / 7.5 days", "6 दिन / 6 days"], "a": 2, "e": "कुल कार्य = 6 x 5 = 30 मानव-दिन; 30 / 4 = 7.5 दिन।\nWork = 6 x 5 = 30 man-days; 30 / 4 = 7.5 days.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "सब्जी और जूट पर माहू (aphid) के भारी प्रकोप से प्रायः कौन सा द्वितीयक रोग होता है?\nHeavy aphid infestation on vegetable and jute crops commonly leads to which secondary disease?", "o": ["पत्ती के नीचे रतुआ फफोले / Rust pustules on leaf underside", "कोमल टहनियों पर चूर्णिल आसिता / Powdery mildew on young shoots", "मधुस्राव वाली पत्तियों पर काली फफूँद (sooty mould) / Sooty mould on honeydew-coated leaves", "फल पर anthracnose / Anthracnose on fruit surface"], "a": 2, "e": "माहू मधुस्राव (honeydew) छोड़ते हैं, जिस पर Capnodium जैसी sooty mould उगती है और प्रकाश संश्लेषण घटता है।\nAphids excrete honeydew on which sooty mould (e.g. Capnodium) grows, reducing photosynthesis.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "किसान कॉल सेंटर (Kisan Call Centre) किसानों को मुख्यतः क्या देता है?\nThe Kisan Call Centre service primarily provides farmers with:", "o": ["टोल-फ्री फोन पर कृषि सलाह / Toll-free telephonic farm advisory", "खेत पर प्रदर्शन प्लॉट / On-farm demonstration plots", "सब्सिडी वाला ऋण / Subsidised credit disbursal", "घर-घर बीज वितरण / Door-to-door seed distribution"], "a": 0, "e": "21 जनवरी 2004 से; टोल-फ्री नंबर 1800-180-1551, स्थानीय भाषा में सलाह।\nStarted 21 Jan 2004; toll-free number 1800-180-1551 with advice in local languages.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "परपरागित फसलों में अंतःप्रजनन अवसाद (inbreeding depression) मुख्यतः किसके बढ़ने से होता है?\nInbreeding depression in cross-pollinated crops results mainly from increased expression of:", "o": ["समयुग्मजी हानिकारक अप्रभावी एलील / Homozygous deleterious recessive alleles", "सहलग्न marker जीन / Linked marker gene combinations", "विषमयुग्मजी लाभकारी प्रभावी एलील / Heterozygous dominant favourable alleles", "Cytoplasmic male sterility जीन / Cytoplasmic male sterility genes"], "a": 0, "e": "Inbreeding से homozygosity बढ़ती है, छिपे हानिकारक recessive जीन प्रकट होकर ओज (vigour) घटाते हैं।\nInbreeding raises homozygosity, exposing deleterious recessive alleles and lowering vigour.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "गहरी जुताई द्वारा कठोर उप-सतही परतों को पलटने व तोड़ने वाली जुताई कौन सी है?\nWhich type of tillage inverts and breaks up compacted subsurface layers through deep ploughing?", "o": ["न्यूनतम (Minimum) / Minimum", "संरक्षण (Conservation) / Conservation", "द्वितीयक (Secondary) / Secondary", "प्राथमिक (Primary) / Primary"], "a": 3, "e": "Primary tillage (MB plough, disc plough, subsoiler) मिट्टी को काटती और पलटती है; secondary tillage (harrow, cultivator) सतह को महीन करती है।\nPrimary tillage cuts and inverts soil; secondary tillage only refines the surface.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उद्यानिकी की शाखा पोमोलॉजी (Pomology) किन फसलों के अध्ययन से संबंधित है?\nPomology, as a branch of horticulture, specifically deals with:", "o": ["रोपण व मसाला फसलें / Plantation and spice crops", "शोभाकारी पुष्प पौधे / Cultivation of ornamental flowering plants", "फल फसलों का उत्पादन व प्रबंधन / Production and management of fruit crops", "सब्जी फसलें (Olericulture) / Vegetable crops"], "a": 2, "e": "Pomology = फल; Olericulture = सब्जी; Floriculture = फूल।\nPomology = fruits; olericulture = vegetables; floriculture = flowers.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कृषि प्रसार में 'परिवर्तन अभिकर्ता' (change agent) मुख्यतः क्या करता है?\nA 'change agent' in agricultural extension primarily functions to:", "o": ["किसानों को संसाधन तंत्र (resource system) से जोड़ना / Link farmers with resource system", "पारंपरिक नेताओं को हटाना / Replace farmers' traditional leaders", "स्वतंत्र कृषि अनुसंधान करना / Conduct independent agri research", "सब्सिडी वितरण की निगरानी / Supervise subsidy disbursal"], "a": 0, "e": "Change agent (Rogers) client system और resource system के बीच कड़ी है, नवाचार अपनाने में मदद करता है।\nA change agent links the client system with the resource system and promotes adoption.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्तर-पूर्वी पहाड़ों में खासी मैंडरिन (Khasi mandarin) के व्यावसायिक गुणन हेतु सामान्यतः कौन सी विधि अपनाई जाती है?\nFor commercial multiplication of Khasi mandarin in the NE hills, which vegetative method is most commonly used?", "o": ["mist में कोमल कलम / Softwood cuttings under mist", "बीजू मूलवृंत पर कलिकायन (budding) / Budding onto seedling rootstock", "परिपक्व शाखाओं पर गूटी / Air layering of mature shoots", "निचली शाखाओं की साधारण दाब कलम / Simple layering of low branches"], "a": 1, "e": "Mandarin में T-budding (Rough lemon / Rangpur lime / Trifoliate बीजू मूलवृंत पर) मानक व्यावसायिक विधि है।\nT-budding on seedling rootstocks (rough lemon, Rangpur lime, trifoliate) is the standard commercial method.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प. बंगाल व ओडिशा की धान आधारित फसल प्रणाली में फसल चक्र मृदा-जनित रोगों को मुख्यतः कैसे नियंत्रित करता है?\nIn rice-based systems, crop rotation helps manage soil-borne diseases mainly through which mechanism?", "o": ["खरपतवार बीज भंडार घटाना / Reducing weed seed bank", "जैविक पदार्थ बढ़ाना / Increasing soil organic matter", "नाइट्रोजन स्थिरीकरण बढ़ाना / Improving N fixation capacity", "परपोषी की अनुपस्थिति से रोगजनक जीवन चक्र टूटना / Breaking pathogen life cycle by host absence"], "a": 3, "e": "Non-host फसल लगाने से रोगजनक को भोजन नहीं मिलता और उसकी संख्या (inoculum) घटती है।\nA non-host crop starves the pathogen and lowers soil inoculum.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प्याज और लहसुन को किस खाद्य भाग के आधार पर सब्जी में वर्गीकृत किया जाता है?\nOnion and garlic are classified as vegetables based on which edible plant part?", "o": ["मोटी पत्ती-आधारों से बना शल्क कंद (bulb) / Bulb formed from thickened leaf bases", "गाँठों वाला प्रकंद (rhizome) / Underground rhizome with nodes", "रूपांतरित भूमिगत तना कंद (tuber) / Modified underground stem tuber", "मांसल मूसला जड़ / Fleshy swollen taproot"], "a": 0, "e": "Bulb एक छोटे चपटे तने (disc) पर मांसल शल्क पत्तियों से बनता है; लहसुन में cloves।\nA bulb is a short disc stem bearing fleshy scale leaves; garlic has cloves.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "रोपित धान (transplanted rice) में सिंचाई निर्धारण हेतु सबसे क्रांतिक अवस्था कौन सी है?\nIn transplanted rice, which growth stage is most critical for irrigation scheduling?", "o": ["पौधशाला / Seedling nursery stage", "खेत तैयारी / Land preparation stage", "बाली निकलने की शुरुआत (panicle initiation) / Panicle initiation stage", "परिपक्वता के बाद / Post-maturity stage"], "a": 2, "e": "धान में panicle initiation से फूल आने (flowering) तक पानी की कमी से उपज सबसे अधिक घटती है।\nWater stress from panicle initiation to flowering causes the greatest yield loss in rice.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 (NFSA) मुख्यतः क्या प्रदान करता है?\nThe National Food Security Act, 2013 primarily aims to provide what?", "o": ["गरीब परिवारों को सस्ता अनाज / Subsidised grain to poor households", "कृषि ऋण पर ब्याज छूट / Interest subvention on farm loans", "MSP गारंटी / Minimum support price guarantee", "सभी किसानों को फसल बीमा / Crop insurance to all farmers"], "a": 0, "e": "NFSA में 5 kg अनाज प्रति व्यक्ति प्रति माह (AAY को 35 kg/परिवार); अब PMGKAY के अंतर्गत मुफ्त।\nNFSA gives 5 kg grain per person per month (AAY 35 kg/family), now free under PMGKAY.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "पूर्णिया (बिहार) में मक्का का बीज दर 20 kg/ha है। किसान 7.5 ha में 15 kg के बीज बैग से बुवाई करता है। कितने बैग चाहिए?\nMaize seed rate is 20 kg/ha. A farmer sows 7.5 ha using 15 kg seed bags. How many bags are needed?", "o": ["9", "10", "12", "8"], "a": 1, "e": "20 x 7.5 = 150 kg; 150 / 15 = 10 बैग।\n20 x 7.5 = 150 kg; 150 / 15 = 10 bags.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कृषि सब्सिडी में प्रत्यक्ष लाभ अंतरण (DBT) का मुख्य अर्थ क्या है?\nDirect Benefit Transfer (DBT) in agricultural subsidies mainly means what?", "o": ["गाँव की सहकारी समिति से भुगतान / Paid via village cooperatives", "बीमा प्रीमियम में समायोजन / Adjusted in insurance premium", "सीधे बैंक खाते में जमा / Credited straight to bank account", "मुफ्त कृषि आदान के रूप में / Given as free farm inputs"], "a": 2, "e": "DBT (1 जनवरी 2013) में लाभ आधार-जुड़े बैंक खाते में सीधे जाता है, जैसे PM-KISAN।\nDBT (from 1 Jan 2013) credits benefits directly to Aadhaar-linked accounts, e.g. PM-KISAN.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "सादृश्य पूरा करें: बीज : पौध (Sapling) :: अंडा : ?\nComplete the analogy: Seed : Sapling :: Egg : ?", "o": ["लार्वा / Larva", "छिलका / Shell", "घोंसला / Nest", "चूजा / Chick"], "a": 3, "e": "बीज से पौध निकलती है, वैसे ही अंडे से चूजा निकलता है।\nA sapling grows from a seed; a chick hatches from an egg.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उच्च ESP, उच्च pH, खराब संरचना परन्तु कम घुलनशील लवण वाली मृदा कहलाती है:\nA soil with high ESP, high pH and poor structure but low soluble salts is called:", "o": ["अम्ल सल्फेट मृदा / Acid sulphate soil", "सोडिक (क्षारीय) मृदा / Sodic (alkali) soil", "लवणीय मृदा / Saline (non-sodic) soil", "लवणीय-सोडिक मृदा / Saline-sodic soil"], "a": 1, "e": "Sodic: ESP > 15, pH > 8.5, ECe < 4 dS/m; सुधार हेतु जिप्सम।\nSodic soil: ESP > 15, pH > 8.5, ECe < 4 dS/m; reclaimed with gypsum.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कटक की सहकारी दुकान में Grade A उर्वरक (20% N) और Grade B (10% N) है। 14% N मिश्रण के लिए किस अनुपात में मिलाएँ?\nGrade A fertilizer has 20% N and Grade B has 10% N. In what ratio must they mix for a 14% N blend?", "o": ["2:3", "4:3", "3:2", "1:2"], "a": 0, "e": "Alligation: A : B = (14 - 10) : (20 - 14) = 4 : 6 = 2 : 3।\nAlligation: A : B = (14 - 10) : (20 - 14) = 4 : 6 = 2 : 3.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "धान की पुआल की पलवार (mulch) से मृदा सतह ढकने पर मुख्यतः किसमें उतार-चढ़ाव कम होता है?\nCovering the soil surface with rice straw mulch mainly moderates fluctuations in:", "o": ["लवणता स्तर / Soil salinity level", "सूक्ष्मजीव संख्या / Soil microbial count", "मृदा तापमान / Soil temperature regime", "मृदा पोषक स्थिति / Soil nutrient status"], "a": 2, "e": "Mulch दिन में गर्मी और रात में ठंड से बचाकर मृदा तापमान स्थिर रखता है तथा वाष्पीकरण घटाता है।\nMulch buffers day-night soil temperature and also cuts evaporation.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "न्यून सिंचाई (deficit irrigation) का अर्थ है जानबूझकर पानी देना:\nDeficit irrigation refers to the deliberate practice of applying water:", "o": ["पूर्ण आवश्यकता से अधिक / Above full crop water requirement", "केवल sprinkler से / Through sprinkler systems only", "केवल रात में / Only during the night hours", "फसल की पूर्ण जल आवश्यकता से कम / Below full crop water requirement"], "a": 3, "e": "कम संवेदनशील अवस्थाओं में ET से कम पानी देकर जल उत्पादकता (WUE) बढ़ाई जाती है।\nWater below full ET is given at less sensitive stages to raise water productivity.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "भूमि चकबंदी (land consolidation) कार्यक्रम किस समस्या को हल करने हेतु है?\nLand consolidation programmes mainly aim to resolve problems arising from:", "o": ["अधिक मशीनीकरण लागत / Excessive mechanization costs", "अनियमित contract farming / Unregulated contract farming deals", "रासायनिक उर्वरक का अधिक प्रयोग / Overuse of chemical fertilizers", "जोतों का टुकड़ों में बँटना / Fragmentation of holdings into plots"], "a": 3, "e": "चकबंदी में बिखरे खेतों को मिलाकर एक या कम चक बनाए जाते हैं।\nScattered plots are pooled into one or fewer compact blocks.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "फर्टिगेशन (fertigation) में घुलनशील उर्वरक फसल को किसके द्वारा दिए जाते हैं?\nFertigation involves applying soluble fertilizers to crops through:", "o": ["बेसल छिड़काव विधि / Basal broadcasting method", "पर्णीय छिड़काव यंत्र / Foliar spray equipment", "बीज उपचार ड्रम / Seed treatment drums", "सिंचाई जल प्रणाली / The irrigation water system"], "a": 3, "e": "Fertigation प्रायः drip से, जिससे पोषक तत्व सीधे जड़ क्षेत्र में पहुँचते हैं और 25-30% उर्वरक बचता है।\nUsually via drip; nutrients reach the root zone with notable fertilizer saving.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "निम्न में से कौन सी प्रसार विधि सामूहिक संपर्क (mass contact) विधि है?\nWhich extension method is classified as a mass contact method?", "o": ["रेडियो कृषि प्रसारण / Radio farm broadcast", "किसान समूह बैठक / Farmers' group meeting", "खेत व घर भेंट / Farm and home visit", "परिणाम प्रदर्शन / Result demonstration plot"], "a": 0, "e": "Individual: farm-home visit; Group: meeting, demonstration; Mass: radio, TV, अखबार, प्रदर्शनी।\nIndividual: farm visit; group: meetings, demonstrations; mass: radio, TV, press.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "भारात्मक विधि (gravimetric method) मृदा नमी किस आधार पर मापती है?\nThe gravimetric method measures soil moisture content based on:", "o": ["न्यूट्रॉन प्रकीर्णन / Neutron scattering", "विद्युत प्रतिरोध / Electrical resistance of soil", "matric suction पाठ्यांक / Soil matric suction reading", "ओवन में सुखाने पर भार में कमी / Loss in weight on oven drying"], "a": 3, "e": "नमूने को 105 डिग्री C पर स्थिर भार तक सुखाते हैं; यह मानक (standard) विधि है।\nSample is oven-dried at 105 degree C to constant weight; it is the standard method.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "द्विसंकर क्रॉस (AaBb x AaBb) की F2 पीढ़ी में कितने अलग लक्षणप्ररूप (phenotypic classes) होते हैं?\nIn a dihybrid cross (AaBb x AaBb), the F2 generation shows how many distinct phenotypic classes?", "o": ["तीन / Three", "सोलह / Sixteen", "दो / Two", "चार / Four"], "a": 3, "e": "9:3:3:1 = 4 phenotype; genotype 9; संयोजन 16।\n9:3:3:1 gives 4 phenotypes; 9 genotypes; 16 combinations.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्तर बिहार के गन्ना क्षेत्र में कटाई के बाद ठूँठ (stubble) से नई फसल लेने की प्रणाली कौन सी है?\nWhich cropping system raises a new crop from stubble regrowth left after harvest?", "o": ["रिले / Relay", "पेड़ी (Ratoon) / Ratoon", "बहु फसली / Multiple", "मिश्रित / Mixed"], "a": 1, "e": "गन्ने में आमतौर पर 1-2 पेड़ी फसलें ली जाती हैं।\nSugarcane usually gives 1-2 ratoon crops.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "पूर्णिया के मक्का क्षेत्र में कूँड़ सिंचाई (furrow), क्यारी (border) के विपरीत, किस फसल के लिए उपयुक्त है?\nFurrow irrigation, unlike border irrigation, is best suited for which type of crop?", "o": ["बाग की थाला सिंचाई / Orchard basin irrigation", "घनी बोई फसलें जैसे गेहूँ / Closely sown crops like wheat", "जलमग्न धान / Flooded rice cultivation", "पंक्ति वाली फसलें जैसे मक्का / Row-planted crops like maize"], "a": 3, "e": "Furrow: पंक्ति फसलें (मक्का, गन्ना, आलू); Border: घनी फसलें (गेहूँ, चारा)।\nFurrow suits row crops (maize, sugarcane, potato); border suits close-growing crops.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मालदा के किसान ने उर्वरक पर 18,000 रु. खर्च किए और उपज 23,400 रु. में बेची। लाभ प्रतिशत ज्ञात करें।\nA farmer spent Rs. 18,000 on fertilizer and sold the produce for Rs. 23,400. Find the profit percentage.", "o": ["23%", "30%", "35%", "24%"], "a": 1, "e": "लाभ = 5,400; (5,400 / 18,000) x 100 = 30%।\nProfit = 5,400; (5,400 / 18,000) x 100 = 30%.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कविता (इकलौती बेटी) ने कहा, 'वह मेरे पिता की इकलौती बेटी का बेटा है।' लड़का कविता का कौन है?\nKavita, an only daughter, said, 'He is the son of my father's only daughter.' How is the boy related to Kavita?", "o": ["भाई / Brother", "भतीजा / Nephew", "पोता / Grandson", "बेटा / Son"], "a": 3, "e": "पिता की इकलौती बेटी = स्वयं कविता; अतः लड़का उसका बेटा है।\nFather's only daughter = Kavita herself, so the boy is her son.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मालदा के आम में नियंत्रित वातावरण (CA) भंडारण से भंडारण अवधि मुख्यतः किसके नियमन से बढ़ती है?\nFor mangoes, Controlled Atmosphere storage extends shelf life mainly by regulating:", "o": ["कमरे में प्रकाश तीव्रता / Storage room light intensity", "केवल तापमान व आर्द्रता / Temperature and humidity alone", "ऑक्सीजन और कार्बन डाइऑक्साइड सांद्रता / Oxygen and carbon dioxide concentration", "केवल एथिलीन सांद्रता / Ethylene gas concentration alone"], "a": 2, "e": "कम O2 और अधिक CO2 से श्वसन और पकना धीमा होता है।\nLow O2 and high CO2 slow respiration and ripening.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "एक कोड में GRAIN को HSBJO लिखा जाता है। उसी कोड में WHEAT कैसे लिखा जाएगा?\nIn a code, GRAIN is written as HSBJO. How is WHEAT written?", "o": ["XHFBU", "XIFBU", "WIFBU", "XIFCU"], "a": 1, "e": "हर अक्षर +1: W-X, H-I, E-F, A-B, T-U = XIFBU।\nEach letter +1: W-X, H-I, E-F, A-B, T-U = XIFBU.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "संकर बीज उत्पादन में CMS (cytoplasmic male sterility) मुख्यतः किसकी आवश्यकता समाप्त करता है?\nCytoplasmic male sterility (CMS) is used in hybrid seed production mainly to eliminate the need for:", "o": ["रासायनिक संकरण कारक / Chemical hybridizing agent application", "जनक लाइनों के बीच पृथक्करण दूरी / Isolation distance between parent lines", "मादा जनक का हाथ से विपुंसन (emasculation) / Manual emasculation of the female parent", "restorer लाइन का स्वपरागण / Selfing of the restorer parent line"], "a": 2, "e": "A-line (CMS) पराग नहीं बनाती, इसलिए हाथ से नर भाग हटाने की जरूरत नहीं; A x R से संकर बीज।\nThe CMS A-line sheds no pollen, so no hand emasculation; A x R gives hybrid seed.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "नई तकनीक से उत्तर बिहार में गेहूँ उपज 3,200 kg/ha से 3,840 kg/ha हो गई। प्रतिशत वृद्धि ज्ञात करें।\nA new technique raised wheat yield from 3,200 kg/ha to 3,840 kg/ha. Find the percentage increase.", "o": ["20%", "17%", "25%", "18%"], "a": 0, "e": "वृद्धि = 640; (640 / 3,200) x 100 = 20%।\nIncrease = 640; (640 / 3,200) x 100 = 20%.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "परपरागित फसलों में स्व-असंगति (self-incompatibility) निषेचन को मुख्यतः किसे रोककर बाधित करती है?\nSelf-incompatibility in cross-pollinated crops blocks fertilization mainly by preventing:", "o": ["परागण से पहले बीजांड विकास / Ovule development before pollination", "स्व-वर्तिकाग्र पर पराग नलिका वृद्धि / Pollen tube growth on self stigma", "फूल आने पर परागकोश स्फुटन / Anther dehiscence at flowering", "परागकोश में पराग बनना / Pollen grain formation in anthers"], "a": 1, "e": "पराग और स्त्रीकेसर दोनों सक्षम होते हैं, परन्तु S-alleles के कारण स्वयं के पराग की नलिका नहीं बढ़ती (जैसे Brassica)।\nBoth pollen and pistil are functional, but S-alleles stop self pollen tube growth (e.g. Brassica).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "हाइड्रोपोनिक्स (hydroponics) में पौधे किस माध्यम में उगाए जाते हैं?\nHydroponic cultivation primarily grows plants in which type of rooting medium?", "o": ["निर्जीवीकृत बलुई दोमट मिट्टी / Sterilized sandy loam soil", "मिट्टी रहित पोषक घोल / Nutrient solution without soil", "कोकोपीट और वर्मीकम्पोस्ट / Coco-peat and vermicompost mix", "कम्पोस्ट FYM / Composted organic farmyard manure"], "a": 1, "e": "Hydroponics = मृदा रहित खेती; जड़ें पोषक घोल में (जैसे NFT प्रणाली)।\nSoilless culture with roots in nutrient solution (e.g. NFT).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "दार्जिलिंग और डुआर्स के चाय बागानों में तीव्र ढलान को समतल सीढ़ियों में बदलकर कटाव रोकना कहलाता है:\nConverting steep hilly slopes into a series of level steps for erosion control is termed:", "o": ["सीढ़ीदार बेंच टैरेसिंग / Bench terracing", "समोच्च मेड़बंदी / Contour bunding", "ढालयुक्त मेड़बंदी / Graded bunding", "पट्टीदार खेती / Strip cropping"], "a": 0, "e": "Bench terracing 16-33% जैसे तीव्र ढलानों पर अपनाई जाती है।\nBench terracing is used on steep slopes (about 16-33%).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "एक ट्रक बर्दवान से कोलकाता बाजार 150 km, 50 km/h से जाता है और खाली 60 km/h से लौटता है। औसत चाल ज्ञात करें।\nA truck carries produce 150 km at 50 km/h and returns empty at 60 km/h. Find the average speed.", "o": ["55 km/h", "50 km/h", "54.5 km/h", "52 km/h"], "a": 2, "e": "समान दूरी पर औसत = 2xy / (x + y) = 2 x 50 x 60 / 110 = 54.5 km/h।\nAverage = 2xy / (x + y) = 6000 / 110 = 54.5 km/h.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "भारत में 'नीली क्रांति' (Blue Revolution) मुख्यतः किस क्षेत्र से संबंधित है?\nThe 'Blue Revolution' in India primarily refers to growth in which sector?", "o": ["मत्स्य पालन और जलीय कृषि / Fisheries and aquaculture", "डेयरी और दूध / Dairy and milk production", "उद्यानिकी निर्यात / Horticulture crop exports", "खाद्यान्न उत्पादन / Foodgrain production"], "a": 0, "e": "Blue = मछली; White = दूध; Yellow = तिलहन; Golden = उद्यानिकी/शहद।\nBlue = fish; White = milk; Yellow = oilseeds; Golden = horticulture/honey.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कटक का किसान 8 km पूर्व चलता है, बाएँ मुड़कर 6 km, फिर बाएँ मुड़कर 8 km चलता है। आरंभ बिंदु से दूरी?\nA farmer walks 8 km east, turns left and walks 6 km, then turns left again and walks 8 km. Find his distance from start.", "o": ["14 km", "6 km", "8 km", "10 km"], "a": 1, "e": "पूर्व 8, उत्तर 6, पश्चिम 8: पूर्व-पश्चिम निरस्त, दूरी = 6 km (उत्तर में)।\nEast 8, north 6, west 8: east-west cancel, so 6 km north of start.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "धान सघनीकरण प्रणाली (SRI) में पौध किस आयु पर रोपी जाती है?\nUnder the System of Rice Intensification, seedlings are transplanted at an age of:", "o": ["20 से 25 दिन / 20 to 25 days", "40 से 45 दिन / 40 to 45 days", "30 से 35 दिन / 30 to 35 days", "8 से 12 दिन / 8 to 12 days"], "a": 3, "e": "SRI (मेडागास्कर, Henri de Laulanie): 8-12 दिन की पौध (2 पत्ती), एक पौध प्रति hill, 25 x 25 cm।\nSRI: 8-12 day (2-leaf) seedlings, single seedling per hill, 25 x 25 cm.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मालदा के बागों में नई (ऊपरी) पत्तियों तक सीमित समान पीलापन, नाइट्रोजन कमी के विपरीत, किसकी कमी दर्शाता है?\nUniform yellowing confined to younger leaves, unlike nitrogen deficiency, indicates deficiency of:", "o": ["सल्फर (S) / Sulphur (S)", "आयरन (Fe) / Iron (Fe)", "जिंक (Zn) / Zinc (Zn)", "नाइट्रोजन (N) / Nitrogen (N)"], "a": 0, "e": "S अचल है, इसलिए नई पत्तियाँ पूरी पीली; N चल है, इसलिए पुरानी पत्तियाँ पीली। Fe में नई पत्तियों में interveinal chlorosis होता है।\nS is immobile, so young leaves turn uniformly yellow; N affects older leaves; Fe gives interveinal chlorosis.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "फार्म बजट में कृषि मशीनरी का मूल्यह्रास (depreciation) किस प्रकार की लागत है?\nDepreciation on farm machinery is classified as which type of cost in farm budgeting?", "o": ["छोड़े गए उपयोग की अवसर लागत / Opportunity cost of foregone use", "अतिरिक्त उत्पादन की सीमांत लागत / Marginal cost of extra output", "परिवर्ती लागत, उत्पादन से जुड़ी / Variable cost, tied to output level", "स्थिर लागत, उत्पादन से स्वतंत्र / Fixed cost, independent of output"], "a": 3, "e": "DIRTI = Depreciation, Interest, Repairs (सामान्य), Taxes, Insurance: स्थिर लागतें।\nDIRTI (depreciation, interest, repairs, taxes, insurance) are fixed costs.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "PPV&FR अधिनियम के अंतर्गत नई किस्म पंजीकरण योग्य होती है यदि वह:\nUnder the PPV&FR Act, a new plant variety qualifies for registration if it is:", "o": ["GM और पेटेंटेड / Genetically modified and patented", "संकर और वानस्पतिक प्रवर्धित / Hybrid and vegetatively propagated", "अधिक उपज और कीट प्रतिरोधी / High yielding and pest resistant", "नवीन, विशिष्ट, एकरूप और स्थिर (NDUS) / Novel, distinct, uniform and stable"], "a": 3, "e": "PPV&FR Act 2001: Novelty + DUS (Distinctiveness, Uniformity, Stability) परीक्षण।\nPPV&FR Act 2001 requires novelty plus DUS (distinctiveness, uniformity, stability).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "किसानों को सहकारी समूहों में संगठित करने से मुख्यतः क्या संभव होता है?\nOrganizing farmers into cooperative groups mainly helps to:", "o": ["प्रसार कर्मचारियों की जरूरत खत्म / Eliminate need for extension staff", "किसानों का सामूहिक मोलभाव / Enable farmers' collective bargaining", "सरकारी योजनाओं का स्थान लेना / Replace government agricultural schemes", "देश भर में किस्मों का मानकीकरण / Standardize crop varieties nationally"], "a": 1, "e": "समूह (सहकारी, FPO) से आदान खरीद और उपज बिक्री में मोलभाव शक्ति बढ़ती है।\nGroups such as cooperatives and FPOs raise bargaining power in buying inputs and selling produce.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "APMC अधिनियम मुख्यतः किसके नियमन हेतु बनाया गया?\nThe APMC Act was primarily enacted to regulate what?", "o": ["नियंत्रित बाजारों में उपज की बिक्री / Sale of produce in regulated markets", "भूजल उपयोग / Groundwater use for irrigation", "नई किस्मों का पंजीकरण / Registration of new seed varieties", "उर्वरक व बीज आयात / Import of fertilizers and seeds"], "a": 0, "e": "राज्य APMC अधिनियम कृषि उपज की खरीद-बिक्री को विनियमित बाजारों में नियंत्रित करते हैं; Model APMC Act 2003।\nState APMC Acts regulate sale of farm produce in notified markets; Model APMC Act 2003.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "1970 में शुरू ऑपरेशन फ्लड (Operation Flood) किस क्षेत्र से संबंधित था?\nOperation Flood, launched in 1970, was primarily associated with which sector?", "o": ["तिलहन आत्मनिर्भरता / Oilseed self-sufficiency drive", "डेयरी सहकारी विकास / Dairy cooperative development", "दलहन मिशन / Pulses production mission", "मत्स्य उत्पादन / Fisheries production boost"], "a": 1, "e": "NDDB द्वारा, डॉ. वर्गीज कुरियन के नेतृत्व में (श्वेत क्रांति), Anand pattern सहकारी।\nRun by NDDB under Dr. Verghese Kurien (White Revolution), on the Anand pattern.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "पकती खड़ी फसल में कटाई से पहले अगली फसल बोना कहलाता है:\nSowing a succeeding crop in the standing field of a maturing crop before harvest is called:", "o": ["मिश्रित फसल / Mixed cropping", "रिले फसल (Relay cropping) / Relay cropping", "पेड़ी फसल / Ratoon cropping", "अंतर फसल / Intercropping"], "a": 1, "e": "जैसे धान में कटाई से पहले मसूर/खेसारी की उतेरा (paira) बुवाई।\nE.g. utera/paira sowing of lentil or lathyrus in standing rice.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "किसान क्रेडिट कार्ड (KCC) योजना मुख्यतः किसानों को क्या देती है?\nThe Kisan Credit Card scheme is designed mainly to provide farmers with:", "o": ["समय पर अल्पकालिक उत्पादन ऋण / Timely short-term production credit", "MSP गारंटी / Guaranteed minimum support price", "मशीनरी ऋण पर सब्सिडी / Subsidised farm machinery loans", "मुफ्त फसल बीमा / Free comprehensive crop insurance cover"], "a": 0, "e": "KCC (1998, NABARD/RBI): 7% ब्याज, समय पर चुकाने पर 3% छूट (प्रभावी 4%)।\nKCC (1998): 7% interest with 3% prompt-repayment incentive (effective 4%).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "फूल जल्दी लाने हेतु बीज या पौध को कम तापमान में रखना कहलाता है:\nExposure of seeds or seedlings to low temperature to hasten flowering is termed:", "o": ["दीप्तिकालिता (Photoperiodism) / Photoperiodism", "बसंतीकरण (Vernalization) / Vernalization", "तापकालिता (Thermoperiodism) / Thermoperiodism", "स्तरीकरण (Stratification) / Stratification"], "a": 1, "e": "Vernalization (Lysenko) से शीत की आवश्यकता पूरी होकर पुष्पन जल्दी होता है; stratification बीज सुप्तावस्था तोड़ता है।\nVernalization satisfies the chilling need for flowering; stratification breaks seed dormancy.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "छोटा नागपुर पठार में, खेत तालाब के विपरीत, चेक डैम मुख्यतः किसलिए बनाया जाता है?\nUnlike a farm pond, a check dam is primarily constructed to:", "o": ["पीने का पानी छानना / Filter water for drinking use", "पाइप से पानी वितरण / Distribute water through pipes", "खोदे गड्ढे में पानी भंडारण / Store water in a dug pit", "नाले/धारा के आर-पार पानी रोकना / Impound water across a stream"], "a": 3, "e": "Check dam नाले पर बनी छोटी संरचना है जो बहाव धीमा कर पानी रोकती और भूजल पुनर्भरण करती है।\nA check dam across a drainage line slows runoff, stores water and recharges groundwater.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "फार्म पर कीटनाशी आदर्श रूप से कहाँ रखने चाहिए?\nWhere should pesticides ideally be stored on a farm?", "o": ["ताला बंद भंडार, भोजन से दूर / Locked store away from food", "कार्यालय की खुली अलमारी / Open shelf in the farm office", "पशु आहार के पास बंद शेड / Locked shed near animal feed", "बिना ताले का भंडार, भोजन से दूर / Unlocked store away from food"], "a": 0, "e": "मूल डिब्बे में, ताले में, बच्चों, भोजन और पशु आहार से दूर रखें।\nKeep in original containers, locked, away from children, food and feed.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "संक्रमण हो जाने के बाद रोगजनक को मारने वाला कवकनाशी किस प्रकार की क्रिया दर्शाता है?\nA fungicide that kills the pathogen after infection has already occurred shows which type of action?", "o": ["अंतःप्रवाही (Systemic) / Systemic", "उपचारात्मक (Curative) / Curative", "रक्षात्मक (Protective) / Protective", "उन्मूलक (Eradicant) / Eradicant"], "a": 1, "e": "Protective = संक्रमण से पहले; Curative/therapeutic = संक्रमण के बाद ऊतक में रोगजनक नष्ट; Systemic = पौधे में फैलने का गुण।\nProtective acts before infection; curative kills the pathogen after infection; systemic describes movement in the plant.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प. बंगाल में आलू की अनुबंध खेती (contract farming) में मूल्य और मात्रा प्रायः कब तय होती है?\nIn potato contract farming, the price and quantity of produce are typically agreed upon:", "o": ["बाजार नीलामी के बाद / After market auction is held", "ग्रेडिंग के बाद ही / Only after produce is graded", "फसल कटाई से पहले / Before the crop is harvested", "APMC बोली द्वारा / Through APMC regulated bidding"], "a": 2, "e": "Contract farming में बुवाई से पहले ही खरीदार और किसान के बीच मूल्य-मात्रा का अनुबंध होता है।\nPrice and quantity are fixed in an agreement before sowing or harvest.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "जैव उर्वरक के रूप में फॉस्फेट घुलनशील जीवाणु (PSB) मुख्यतः कैसे कार्य करते हैं?\nPhosphate Solubilising Bacteria used as a biofertilizer primarily act by:", "o": ["अघुलनशील फॉस्फेट को घुलनशील बनाना / Converting insoluble phosphates to soluble form", "स्थिर पोटाश खनिज घोलना / Solubilising fixed potassium minerals", "सहजीवी नाइट्रोजन स्थिरीकरण / Fixing atmospheric nitrogen symbiotically", "केवल हार्मोन बनाना / Producing phytohormones exclusively"], "a": 0, "e": "Pseudomonas, Bacillus आदि कार्बनिक अम्ल बनाकर Ca/Fe/Al फॉस्फेट को घोलते हैं।\nPseudomonas and Bacillus release organic acids that dissolve Ca, Fe and Al phosphates.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "श्रेणी का अगला अंक ज्ञात करें: 2, 5, 10, 17, 26, ?\nFind the next number in the series: 2, 5, 10, 17, 26, ?", "o": ["36", "35", "37", "38"], "a": 2, "e": "अंतर 3, 5, 7, 9, 11 (या n वर्ग + 1): 26 + 11 = 37।\nDifferences 3, 5, 7, 9, 11 (n squared + 1): 26 + 11 = 37.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "धान कटाई में कंबाइन हार्वेस्टर का header और reel सबसे अधिक उलझने का खतरा कब पैदा करते हैं?\nA combine harvester's header and reel pose the greatest entanglement risk when:", "o": ["सुबह कटाई होने पर / Harvesting occurs at dawn", "खेत में हल्की ढलान होने पर / The field has a gentle slope", "मशीन धीमी गति पर चलने पर / The machine runs at low speed", "सुरक्षा गार्ड हटाकर चलाने पर / Safety guards are removed in use"], "a": 3, "e": "गार्ड चलते भागों को ढकते हैं; उन्हें हटाने पर कपड़े/अंग फँसने का खतरा सबसे अधिक होता है।\nGuards cover moving parts; removing them sharply raises entanglement risk.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मालदा के आम बागों में फल वृक्षों की छँटाई (pruning) का मुख्य उद्यानिकी उद्देश्य क्या है?\nIn mango orchards, the main horticultural purpose of pruning fruit trees is to achieve:", "o": ["बीज अंकुरण दर बढ़ना / Increased seed germination rate", "बेहतर छत्र आकार और प्रकाश प्रवेश / Improved canopy shape and light entry", "जड़ तंत्र का तेज विकास / Faster root system establishment", "मृदा नमी धारण क्षमता बढ़ना / Higher soil moisture retention capacity"], "a": 1, "e": "छँटाई से धूप-हवा भीतर पहुँचती है, पुराने बागों का जीर्णोद्धार (rejuvenation) होता है और कीट-रोग घटते हैं।\nPruning opens the canopy to light and air, rejuvenates old trees and reduces pests.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "किसी फसल हेतु अपनी भूमि उपयोग करने की अवसर लागत (opportunity cost) बराबर है:\nThe opportunity cost of using owned land for one crop equals the:", "o": ["भूमि सुधार का मूल्यह्रास / Depreciation cost of land improvements", "भूमि का बाजार विक्रय मूल्य / Market sale price of farm land", "भूमि का कुल वार्षिक किराया मूल्य / Total annual rental value of land", "सर्वोत्तम विकल्प से छोड़ी गई आय / Income foregone from best alternative"], "a": 3, "e": "Opportunity cost = अगले सर्वोत्तम उपयोग से मिलने वाली आय जो छोड़ी गई।\nOpportunity cost = return from the next best use that was given up.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मीना कक्षा में ऊपर से 7वीं और नीचे से 15वीं है। कक्षा में कितने विद्यार्थी हैं?\nMeena ranks 7th from the top and 15th from the bottom. How many students are in the class?", "o": ["22", "21", "23", "20"], "a": 1, "e": "कुल = 7 + 15 - 1 = 21।\nTotal = 7 + 15 - 1 = 21.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प. बंगाल व ओडिशा के धान में ब्लास्ट (blast) रोग का विशिष्ट पत्ती लक्षण क्या है?\nRice blast disease is typically identified by which leaf lesion symptom?", "o": ["शिराओं के साथ पीली धारियाँ / Yellowish streaks along leaf veins", "धूसर केंद्र वाले तर्कु (spindle) आकार के धब्बे / Spindle-shaped lesion with grey centre", "समानांतर पंक्तियों में नारंगी-भूरे फफोले / Orange-brown pustules in parallel stripes", "लाल-भूरी पर्णच्छद सड़न / Reddish-brown sheath rot streaks"], "a": 1, "e": "Magnaporthe oryzae (Pyricularia): आँख के आकार के धब्बे, भूरा किनारा व धूसर केंद्र; neck blast से बाली टूटती है।\nMagnaporthe oryzae gives eye-shaped lesions with brown margin and grey centre; also neck blast.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "नदिया (प. बंगाल) में टमाटर का ब्लॉसम एंड रॉट और पत्तागोभी का टिप बर्न किस पोषक तत्व की कमी दर्शाते हैं?\nBlossom end rot in tomato and tip burn in cabbage indicate deficiency of which nutrient?", "o": ["मैग्नीशियम (Mg) / Magnesium (Mg)", "बोरॉन (B) / Boron (B)", "पोटैशियम (K) / Potassium (K)", "कैल्शियम (Ca) / Calcium (Ca)"], "a": 3, "e": "Ca अचल है और कोशिका भित्ति (calcium pectate) हेतु जरूरी; अनियमित सिंचाई से कमी बढ़ती है।\nCa is immobile and needed for calcium pectate in cell walls; irregular watering worsens it.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "हीराकुद और दामोदर घाटी नहर प्रणालियों में संवहन दक्षता (conveyance efficiency) किन जल हानियों को मापती है?\nIn canal systems, conveyance efficiency measures water losses occurring:", "o": ["जड़ क्षेत्र के भीतर / Within the root zone profile", "वाष्पोत्सर्जन के दौरान / During crop evapotranspiration", "स्रोत और खेत नाली के बीच / Between source and field channel", "पत्ती रंध्रों पर / At the leaf stomatal surface"], "a": 2, "e": "Ec = (खेत तक पहुँचा पानी / स्रोत से छोड़ा पानी) x 100; रिसाव (seepage) व वाष्पन हानि शामिल।\nEc = (water reaching field / water released at source) x 100; covers seepage and evaporation.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "हुगली के आलू में Phytophthora infestans जनित पछेती झुलसा (late blight) का पहला पत्ती लक्षण क्या है?\nLate blight of potato, caused by Phytophthora infestans, first appears as which leaf symptom?", "o": ["पत्रकों पर भूरे संकेंद्री छल्ले / Brown concentric rings on leaflets", "तने के आधार पर गहरे भूरे फफोले / Dark brown pustules on stem base", "सफेद फफूँद वाले जलसिक्त धब्बे / Water-soaked lesions with white mould", "पत्तियों पर सफेद चूर्णी धब्बे / Powdery white patches on leaves"], "a": 2, "e": "नम मौसम में पत्ती के नीचे सफेद कवकजाल (sporangia) दिखता है; संकेंद्री छल्ले अगेती झुलसा (Alternaria solani) में होते हैं।\nWhite sporulation appears on the lower leaf surface in humid weather; concentric rings mark early blight.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "उत्परिवर्तन प्रजनन में बिंदु उत्परिवर्तन (point mutation) हेतु कौन सा रासायनिक उत्परिवर्तक सबसे अधिक प्रयुक्त है?\nWhich chemical mutagen is widely used in mutation breeding to induce point mutations?", "o": ["एथिल मीथेन सल्फोनेट (EMS), alkylating agent / Ethyl methane sulfonate, an alkylating agent", "जिबरेलिक अम्ल, पादप हार्मोन / Gibberellic acid, a plant growth hormone", "2,4-D, संश्लेषित ऑक्सिन खरपतवारनाशी / 2,4-D, a synthetic auxin herbicide", "कोल्चिसिन, तर्कु अवरोधक / Colchicine, a mitotic spindle inhibitor"], "a": 0, "e": "EMS मुख्यतः G:C से A:T transition बनाता है; colchicine से गुणसूत्र दोहरे होते हैं (polyploidy), point mutation नहीं।\nEMS mainly causes G:C to A:T transitions; colchicine doubles chromosomes, not point mutations.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "हीराकुद कमांड क्षेत्र में, नलकूप की तुलना में, नहर सिंचाई जल में सामान्यतः अधिक होता है:\nCompared to tube well irrigation, canal irrigation water typically carries more:", "o": ["घुलित लोहा / Dissolved iron content", "निलंबित गाद और तलछट / Suspended silt and sediment", "जल तापमान उतार-चढ़ाव / Water temperature fluctuation", "घुलित लवण / Dissolved soluble salts"], "a": 1, "e": "नदी से आने के कारण नहर जल में गाद अधिक होती है; भूजल में घुलित लवण प्रायः अधिक होते हैं।\nRiver-fed canal water carries silt; groundwater usually has more dissolved salts.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "खेत फसलों में चूर्णिल आसिता (powdery mildew) रोग किस मौसम में सबसे अधिक बढ़ता है?\nPowdery mildew disease development in field crops is most favoured by which weather condition?", "o": ["बिना वर्षा के बादल व नमी वाला मौसम / Cloudy humid weather without rainfall", "तेज धूप व उच्च तापमान / High temperature with intense sunlight", "लगातार वर्षा व जलभराव / Continuous rainfall with waterlogged soil", "कम आर्द्रता व तेज शुष्क हवा / Low humidity with strong dry winds"], "a": 0, "e": "Powdery mildew (Erysiphe) को उच्च आर्द्रता पर पत्ती पर मुक्त जल नहीं चाहिए; वर्षा बीजाणु धो देती है।\nPowdery mildew needs high humidity but not free water; rain washes spores off.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "विषम चुनें: फावड़ा, हँसिया, हल, ट्रैक्टर\nChoose the odd one out: Spade, Sickle, Plough, Tractor", "o": ["हल / Plough", "हँसिया / Sickle", "फावड़ा / Spade", "ट्रैक्टर / Tractor"], "a": 3, "e": "फावड़ा, हँसिया, हल औज़ार/उपकरण हैं; ट्रैक्टर शक्ति स्रोत (power machine) है।\nSpade, sickle and plough are tools or implements; a tractor is a power machine.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "बिहार व प. बंगाल में फैली गाजर घास (Parthenium) पार्थेनिन छोड़कर आसपास के पौधों की वृद्धि रोकती है, यह दर्शाता है:\nParthenium suppresses nearby plant growth by releasing parthenin, illustrating:", "o": ["एलीलोपैथी (Allelopathy) / Allelopathy", "प्रतिस्पर्धा / Competition", "सहजीविता / Symbiosis", "सहोपकारिता / Mutualism"], "a": 0, "e": "Allelopathy (Molisch, 1937) = रसायन (allelochemicals) द्वारा दूसरे पौधों पर प्रभाव; जैव नियंत्रण Zygogramma bicolorata।\nAllelopathy is chemical inhibition of other plants; biocontrol agent is Zygogramma bicolorata.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "अनेक छोटी उँगली जैसी नालियाँ जो सामान्य जुताई से समतल हो जाती हैं, किस कटाव का संकेत हैं?\nNumerous small, finger-like channels that can be smoothed out by normal tillage describe:", "o": ["अवनालिका अपरदन (Gully) / Gully erosion", "रिल अपरदन (Rill erosion) / Rill erosion", "परत अपरदन (Sheet) / Sheet erosion", "वायु अपरदन / Wind erosion"], "a": 1, "e": "क्रम: Splash, Sheet, Rill, Gully; gully इतनी गहरी कि सामान्य जुताई से नहीं भरती।\nSequence: splash, sheet, rill, gully; gullies cannot be removed by normal tillage.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प्रसार कार्यक्रमों में प्रशिक्षण आवश्यकता आकलन (TNA) मुख्यतः किसलिए किया जाता है?\nTraining Needs Assessment (TNA) in extension programmes is conducted primarily to:", "o": ["पदोन्नति हेतु कर्मचारी चुनना / Select extension staff for promotion", "विभागीय बजट तय करना / Finalize annual departmental budgets", "फसल उपज का मूल्यांकन / Evaluate crop yield performance", "कौशल और ज्ञान की कमियाँ पहचानना / Identify skill and knowledge gaps"], "a": 3, "e": "Training need = वांछित और वर्तमान ज्ञान/कौशल/अभिवृत्ति के बीच का अंतर।\nTraining need = gap between desired and present knowledge, skill and attitude.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "एट्रोपिन (Atropine) किस वर्ग के कीटनाशी विषाक्तता का आपातकालीन प्रतिविष (antidote) है?\nAtropine is used as an emergency antidote for poisoning by which class of pesticide?", "o": ["फिनॉक्सी खरपतवारनाशी / Phenoxy herbicides", "पायरेथ्रॉइड कीटनाशी / Pyrethroid insecticides", "ऑर्गेनोफॉस्फेट कीटनाशी / Organophosphate insecticides", "ट्रायाजोल कवकनाशी / Triazole fungicides"], "a": 2, "e": "OP और carbamate acetylcholinesterase रोकते हैं; atropine sulphate (साथ में PAM, OP हेतु) दिया जाता है।\nOPs and carbamates inhibit acetylcholinesterase; atropine sulphate (plus PAM for OPs) is given.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "ओडिशा के ट्रैक्टर मालिक हेतु मशीन रखने का break-even क्षेत्र वह है जिसके ऊपर मशीन रखना:\nThe break-even area for owning a farm machine is the area beyond which owning becomes:", "o": ["निर्णय हेतु अप्रासंगिक / Irrelevant to hiring decisions", "किराये (custom hiring) से सस्ता / Cheaper than custom hiring", "किराये से महँगा / Costlier than custom hiring", "हमेशा किराये के बराबर / Equal to hiring charges always"], "a": 1, "e": "Break-even क्षेत्र = स्थिर लागत / (किराया दर - परिवर्ती लागत प्रति ha); इससे अधिक उपयोग पर स्वामित्व सस्ता।\nBreak-even area = fixed cost / (hire rate - variable cost per ha); above it ownership is cheaper.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "राष्ट्रीय कृषि विकास योजना (RKVY) मुख्यतः किसे प्रोत्साहित करती है?\nRashtriya Krishi Vikas Yojana (RKVY) mainly aims to incentivize what?", "o": ["किसानों को सीधा नकद / Direct cash transfer to farmers", "राज्यों का कृषि निवेश / States' agricultural investment", "अधिशेष अनाज निर्यात / Export of surplus foodgrains", "पराली जलाने पर नियंत्रण / Crop residue burning control"], "a": 1, "e": "RKVY (2007-08) राज्यों को कृषि व संबद्ध क्षेत्रों में निवेश बढ़ाने हेतु लचीली केंद्रीय सहायता देती है।\nRKVY (2007-08) gives states flexible funds to raise investment in agriculture and allied sectors.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "संकीर्ण अर्थ वंशागतित्व (narrow-sense heritability) व्यापक अर्थ से इस बात में भिन्न है कि यह केवल किस प्रसरण को गिनता है?\nNarrow-sense heritability differs from broad-sense heritability in that it accounts only for which variance component?", "o": ["वातावरण अन्योन्यक्रिया प्रसरण / Environment interaction variance", "प्रभाविता प्रसरण / Dominance genetic variance", "कुल जीनोटाइपिक प्रसरण / Total genotypic variance", "योगात्मक आनुवंशिक प्रसरण / Additive genetic variance"], "a": 3, "e": "h2 (ns) = VA / VP; h2 (bs) = VG / VP। चयन की प्रभावशीलता ns heritability पर निर्भर।\nh2 (ns) = VA / VP; h2 (bs) = VG / VP; selection response depends on narrow-sense h2.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "रोजर्स के नवाचार प्रसार सिद्धांत में नवप्रवर्तकों (innovators) के ठीक बाद नवाचार अपनाने वाली श्रेणी कौन सी है?\nIn Rogers' diffusion of innovations theory, which category adopts immediately after innovators?", "o": ["पिछड़े किसान (Laggards) / Laggard farmers", "शीघ्र अपनाने वाले (Early adopters) / Early adopters", "पश्च बहुमत / Late majority", "शीघ्र बहुमत / Early majority"], "a": 1, "e": "Innovators 2.5%, Early adopters 13.5%, Early majority 34%, Late majority 34%, Laggards 16%।\nInnovators 2.5%, early adopters 13.5%, early majority 34%, late majority 34%, laggards 16%.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "पुरानी पत्तियों में 'क्रिसमस ट्री' आकार की शिरा-मध्य हरिमाहीनता (interveinal chlorosis) किसकी कमी दर्शाती है?\nInterveinal chlorosis of older leaves in a 'Christmas tree' pattern points to deficiency of:", "o": ["मैग्नीशियम (Mg) / Magnesium (Mg)", "पोटैशियम (K) / Potassium (K)", "मैंगनीज (Mn) / Manganese (Mn)", "नाइट्रोजन (N) / Nitrogen (N)"], "a": 0, "e": "Mg क्लोरोफिल का केंद्रीय परमाणु और चल तत्व है, इसलिए पुरानी पत्तियों में interveinal chlorosis।\nMg is the central atom of chlorophyll and mobile, so older leaves show interveinal chlorosis.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कटक के किसान को 3 ha में 32 kg P2O5/ha SSP (16% P2O5) से देना है। SSP 50 kg बैग में है। कितने बैग चाहिए?\nA farmer needs 32 kg P2O5/ha using SSP (16% P2O5) on 3 hectares. SSP comes in 50 kg bags. How many bags are needed?", "o": ["16", "9", "12", "15"], "a": 2, "e": "SSP/ha = 32 x 100 / 16 = 200 kg; 3 ha = 600 kg; 600 / 50 = 12 बैग।\nSSP/ha = 200 kg; 3 ha = 600 kg; 600 / 50 = 12 bags.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "मालदा के व्यावसायिक आम बाग कलम (grafting) द्वारा प्रवर्धन मुख्यतः किस कारण पसंद करते हैं?\nCommercial mango orchards prefer vegetative propagation by grafting mainly for which reason?", "o": ["बीजू पौधों में अधिक जड़ ओज / Higher root vigour in seedlings", "बीजू पौधों में अधिक आनुवंशिक विविधता / Greater genetic variability among seedlings", "गुठली से तेज अंकुरण / Faster germination from stone seed", "फल गुणवत्ता का मातृ-समान (true-to-type) बने रहना / True-to-type fruit quality retention"], "a": 3, "e": "आम परपरागित है, इसलिए बीजू पौधे भिन्न होते हैं; softwood/veneer/stone grafting से मातृ गुण बने रहते हैं।\nMango is cross-pollinated, so seedlings vary; grafting keeps the mother variety's traits.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "कथन: कुछ ट्रैक्टर लाल हैं। सभी लाल चीजें महँगी हैं। निष्कर्ष: I. कुछ ट्रैक्टर महँगे हैं। II. सभी महँगी चीजें ट्रैक्टर हैं।\nStatements: Some tractors are red. All red things are expensive. Conclusions: I. Some tractors are expensive. II. All expensive things are tractors.", "o": ["कोई निष्कर्ष सही नहीं / Neither conclusion follows", "दोनों निष्कर्ष सही / Both conclusions follow", "केवल निष्कर्ष I सही / Only conclusion I follows", "केवल निष्कर्ष II सही / Only conclusion II follows"], "a": 2, "e": "Some + All = Some, अतः I सही; II उलटा सार्वभौमिक कथन है, अनिवार्य नहीं।\nSome + All gives Some, so I follows; II is an unwarranted universal reverse.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "बिहार व प. बंगाल की बाढ़-प्रवण निचली भूमि में रोपित धान की तुलना में सीधी बुवाई धान (DSR) में अधिक समस्या होती है:\nCompared with transplanted rice, direct seeded rice generally faces greater problems of:", "o": ["परिपक्वता पर गिरना / Lodging at maturity", "ब्लास्ट फैलाव / Blast disease spread", "बाली बंध्यता / Panicle sterility", "खरपतवार प्रकोप / Weed infestation levels"], "a": 3, "e": "DSR में शुरुआती जल-भराव नहीं होता और धान-खरपतवार साथ उगते हैं, इसलिए खरपतवार सबसे बड़ी बाधा है।\nDSR lacks early standing water and crop and weeds emerge together, so weeds are the main constraint.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "प्रसार संचार प्रणाली में 'प्रतिपुष्टि' (feedback) परिवर्तन अभिकर्ता को मुख्यतः किसमें मदद करती है?\nIn an extension communication system, 'feedback' primarily helps the change agent to:", "o": ["अतिरिक्त कर्मचारी भर्ती / Recruit additional field staff", "अधिक प्रसार साहित्य छापना / Print more extension literature", "प्रसारण दायरा बढ़ाना / Increase the broadcast transmission range", "संदेश पर किसानों की प्रतिक्रिया आँकना / Assess farmers' response to message"], "a": 3, "e": "Feedback (receiver से sender तक) बताता है कि संदेश समझा व अपनाया गया या नहीं; Berlo का SMCR मॉडल।\nFeedback shows whether the message was understood and accepted.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "ओडिशा में धान सिंचाई निर्धारण में IW/CPE अनुपात मुख्यतः किसे तय करने में प्रयुक्त होता है?\nThe IW/CPE ratio in irrigation water management is primarily used to determine:", "o": ["सिंचाई का समय/अंतराल / Irrigation timing frequency", "नहर संवहन हानि / Canal water conveyance loss", "मृदा नमी ह्रास दर / Soil moisture depletion rate", "खेत जल निकास गुणांक / Field drainage coefficient"], "a": 0, "e": "IW = सिंचाई जल की गहराई, CPE = संचयी पैन वाष्पन; CPE तय मान पहुँचने पर सिंचाई (जैसे IW/CPE 1.0)।\nIW = irrigation depth, CPE = cumulative pan evaporation; irrigate when CPE reaches the set value.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "सांद्र कीटनाशी को घोलने से पहले मिलाते और भरते समय कौन सी सावधानी आवश्यक है?\nWhich precaution is essential while mixing and loading concentrated pesticide, before dilution?", "o": ["बिना दस्ताने के रेनकोट / A raincoat without gloves", "बिना एप्रन के सूती दस्ताने / Cotton gloves without an apron", "रबर के दस्ताने और एप्रन / Rubber gloves and an apron", "केवल सूती धूल मास्क / Only a cotton dust mask"], "a": 2, "e": "सांद्र रसायन सबसे खतरनाक है; रासायनिक-रोधी (rubber/nitrile) दस्ताने और एप्रन पहनें, सूती कपड़ा रसायन सोखता है।\nConcentrate is most hazardous; wear chemical-resistant (rubber/nitrile) gloves and apron; cotton absorbs chemical.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "बर्दवान की सहकारी समिति किसान को 1,20,000 रु. का ऋण 8% साधारण ब्याज पर 15 माह के लिए देती है। ब्याज ज्ञात करें।\nA cooperative gives a loan of Rs. 1,20,000 at 8% simple interest for 15 months. Find the interest.", "o": ["12,000 रु. / Rs. 12,000", "14,400 रु. / Rs. 14,400", "13,200 रु. / Rs. 13,200", "9,600 रु. / Rs. 9,600"], "a": 0, "e": "SI = P x R x T / 100 = 1,20,000 x 8 x (15/12) / 100 = 12,000 रु.।\nSI = 1,20,000 x 8 x 1.25 / 100 = Rs. 12,000.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "झारखंड व पश्चिमी ओडिशा की अम्लीय लेटराइटिक मृदा की चूना आवश्यकता (lime requirement) मुख्यतः किससे तय होती है?\nThe lime requirement of an acid soil is determined mainly from its:", "o": ["जैविक कार्बन / Organic carbon content", "उपलब्ध फॉस्फोरस / Available phosphorus level", "विनिमेय मृदा अम्लता / Exchangeable soil acidity", "धनायन विनिमय क्षमता / Cation exchange capacity"], "a": 2, "e": "LR विनिमेय (और आरक्षित) अम्लता यानी Al3+ व H+ को उदासीन करने पर निर्भर; Shoemaker-McLean-Pratt (SMP) buffer विधि।\nLR depends on neutralising exchangeable (and reserve) acidity, Al3+ and H+; SMP buffer method.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "समूह चयन (mass selection) में पौधों का चयन किस आधार पर होता है?\nMass selection improves population performance by selecting plants based on:", "o": ["कई पीढ़ियों के वंशावली रिकॉर्ड / Pedigree records across several generations", "केवल लक्षणप्ररूप, बिना संतति परीक्षण / Phenotype alone, without progeny testing", "पुनरावृत्त परीक्षणों में संतति प्रदर्शन / Progeny performance in replicated trials", "आणविक marker परिणाम / Molecular marker genotyping results"], "a": 1, "e": "Mass selection सबसे पुरानी विधि है; चयनित पौधों का बीज मिलाकर अगली पीढ़ी उगाई जाती है।\nThe oldest method; seed of phenotypically selected plants is bulked for the next generation.", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "जल स्रोत के पास कीटनाशी छिड़काव का बहाव (drift) रोकने हेतु छिड़काव कर्ता को मुख्यतः क्या करना चाहिए?\nTo prevent pesticide spray drift near a water body, a sprayer operator should mainly do what?", "o": ["पर्याप्त बफर दूरी रखना / Maintain an adequate buffer distance", "सबसे महीन नोज़ल प्रयोग / Use the finest nozzle available", "दबाव तेजी से बढ़ाना / Increase spray pressure fast", "दोपहर की तेज हवा में छिड़काव / Spray during peak afternoon winds"], "a": 0, "e": "तेज हवा, अधिक दबाव और महीन बूँदें drift बढ़ाते हैं; जल स्रोत से buffer zone छोड़ें, शांत समय में छिड़कें।\nWind, high pressure and fine droplets increase drift; keep a buffer zone and spray in calm weather.", "s": "Reasoning/GK/Safety", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}, {"q": "बाजार हस्तक्षेप योजना (MIS) मुख्यतः किन वस्तुओं के मूल्य को सहारा देती है?\nThe Market Intervention Scheme (MIS) mainly supports prices for commodities that are:", "o": ["MSP के बाहर की जल्दी खराब होने वाली फसलें / Perishable crops not under MSP", "केवल डेयरी व मुर्गी उत्पाद / Dairy and poultry products exclusively", "MSP वाले मुख्य अनाज / Staple food grains under MSP", "केवल निर्यात रोपण फसलें / Export-oriented plantation crops only"], "a": 0, "e": "MIS राज्य के अनुरोध पर बागवानी व जल्दी खराब होने वाली (non-MSP) फसलों के दाम 10% गिरने/बम्पर उत्पादन पर लागू होती है (अब PM-AASHA में)।\nMIS covers perishable non-MSP crops on state request when prices crash (now under PM-AASHA).", "s": "Agri Science", "src": "IFFCO AGT 2026, 19 Nov 2026, 1 PM shift (memory based); answers verified by Agrikranti", "cls": "PYQ - IFFCO AGT 2026"}]}]);
